// www.shaderpark.com
// All the code below is javascript that's compiled into a shader

const spCode =  `

  setMaxIterations(18);
  let click = input();
	let buttonHover = input();
  let offset = .1//input(8, 0, 1);
  function fbm(p) {
    return vec3(
      noise(p),
      noise(p+offset),
      noise(p+offset*2),
    )
  }

  let s = getRayDirection();
  let n = sin(fbm(s+vec3(0, 0, -time*.1))*2)*.5+.75;
  n = pow(n, vec3(8));
  color(n)
  let scale =.5+n.x*.05;
	shape(() => {
		rotateX(PI/2);
		rotateX(mouse.x* click)
		rotateZ(-1*mouse.y* click)
		torus(scale, .2)
		reset();
		mixGeo(click)

		sphere(scale);
	})()
  blend(.4)
  displace(mouse.x*2, mouse.y, 0)

  sphere(.2)
`;



